import{z as n,x as i,o as e,c as s,q as t,j as A,D as a,d as l,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"跨期选择的异常","description":"","frontmatter":{"title":"跨期选择的异常","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bx-intertemporal-anomalies.md","filePath":"econ/bx-intertemporal-anomalies.md","lastUpdated":1791413859000}'),d={name:"econ/bx-intertemporal-anomalies.md"};function p(m,E,c,b,D,_){const B=i("Mermaid");return e(),s("div",null,[E[2]||(E[2]=t('<h1 id="跨期选择的异常" tabindex="-1">跨期选择的异常 <a class="header-anchor" href="#跨期选择的异常" aria-label="Permalink to &quot;跨期选择的异常&quot;">​</a></h1><div class="epigraph"><p>「现在」在贴现函数里不是一个时刻，是一处断点：跨过它的那一段间隔，被额外抽了一次折扣。</p><footer>—— 据 Thaler, Economics Letters, 1981；Laibson, Quarterly Journal of Economics, 1997 整理</footer></div><p><a href="/econ/bx-prospect-deep">上一课</a>把风险侧的权重从分离概率改成累积秩依赖，损失厌恶拿到参数 \\(\\lambda\\)。本课把同一套「先分异常、再配表示」的做法搬到时间侧。<a href="/econ/hyperbolic-present-bias">双曲贴现与现时偏差</a>已在主干钉了定义层：指数贴现的相对权重不随起点变，准双曲 \\(\\beta\\)–\\(\\delta\\) 让「现在」额外打折，幼稚与老练自我的策略不同。本课补数据层：哪些异常是贴现函数的形状，哪些是测量协议的伪影，\\(\\beta\\)–\\(\\delta\\) 能吸收几条，吸不住的几条又指回上一课的 \\(v\\)。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指数贴现 \\(u(c_t)+\\delta^{\\tau}u(c_{t+\\tau})\\) 只有一个自由参数，预言隐含贴现率只跟间隔 \\(\\tau\\) 有关，与起点、金额、符号无关。四条异常各击一处。(1) 共同差异效应：「今天的 100 对一周后的 110」多数选今天，「一年后的 100 对一年零一周后的 110」多数选后者——同一个 \\(\\tau\\)，两种问法的隐含贴现率相差几个数量级。(2) 幅度效应：金额放大，隐含贴现率下降。(3) 符号效应：损失侧的隐含贴现率低于收益侧。(4) 延迟—加速不对称：把好结果提前所愿付的代价，小于把同样结果推迟所要求的补偿。缺口不是宣布「人不理性」，而是这四条能否被一个两参数表示同时收编。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>准双曲表示：\\(U^t=u(c_t)+\\beta\\sum_{\\tau\\ge1}\\delta^{\\tau}u(c_{t+\\tau})\\)。它天然吸收共同差异效应：\\(\\beta\\lt1\\) 只作用于跨越「现在」的那段间隔，未来两点之间的相对权重仍由 \\(\\delta\\) 支配——断点正好落在「今天对以后」上。幅度与符号效应它吸不住：金额与符号改变的是效用函数的曲率与斜率，不是贴现结构。接法是把上一课的 \\(v\\) 装进跨期效用：收益凹、损失侧平缓且斜率大 \\(\\lambda\\) 倍，符号效应与延迟—加速不对称在损失编码一侧拿到公共解释——「把坏结果提前」是损失域里的选择，用的是更平的 \\(v\\)。风险侧与时间侧共用一套价值函数，这是本课程把两课排在一起的机制理由。</p><p>测量协议决定 \\(\\beta\\) 的高低。多重价格列表固定远端金额、扫近端找切换点，换远端再扫；前端延迟把两个选项都推到「至少一周之后」，剥离「立刻」的特别吸引力。不剥离时，现时偏差混着立即兑现的交易成本与兴奋，\\(\\beta\\) 被系统性高估。</p><p><span class="marginnote">Thaler 1981 的问卷里，「现在拿 15 美元」与「一年后拿 60 美元」中位无差异，隐含年贴现率约 300%；同一调查里期限越长，隐含贴现率越低。共同差异与幅度效应在同一次调查里同时显形——异常是期限结构，不是孤例。</span></p>',9)),(e(),A(r,null,{default:a(()=>[o(B,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E6%8C%87%E6%95%B0%E8%B4%B4%E7%8E%B0%3A%20%E5%8D%95%E5%8F%82%E6%95%B0%20delta%22%5D%20--%3E%20AN%5B%22%E5%9B%9B%E6%9D%A1%E5%BC%82%E5%B8%B8%3A%20%E5%85%B1%E5%90%8C%E5%B7%AE%E5%BC%82%20%2F%20%E5%B9%85%E5%BA%A6%20%2F%20%E7%AC%A6%E5%8F%B7%20%2F%20%E5%BB%B6%E8%BF%9F%E5%8A%A0%E9%80%9F%22%5D%0A%20%20AN%20--%3E%20BD%5B%22beta%20delta%20%E5%90%B8%E6%94%B6%E5%85%B1%E5%90%8C%E5%B7%AE%E5%BC%82%22%5D%0A%20%20AN%20--%3E%20V%5B%22%E5%90%B8%E4%B8%8D%E4%BD%8F%E7%9A%84%E4%B8%A4%E6%9D%A1%E6%8C%87%E5%9B%9E%E4%BB%B7%E5%80%BC%E5%87%BD%E6%95%B0%20v%22%5D%0A%20%20BD%20--%3E%20MPL%5B%22%E5%A4%9A%E9%87%8D%E4%BB%B7%E6%A0%BC%E5%88%97%E8%A1%A8%E5%8A%A0%E5%89%8D%E7%AB%AF%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20V%20--%3E%20MPL%0A%20%20MPL%20--%3E%20EST%5B%22beta%20%E5%AE%9A%E7%9F%AD%E7%AB%AF%2C%20delta%20%E5%AE%9A%E9%95%BF%E7%AB%AF%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\beta\\) 与 \\(\\delta\\) 的辨识分工：是否跨越「现在」动 \\(\\beta\\)，长端水平动 \\(\\delta\\)；只有含前端延迟变异的设计能把两者分开。自我博弈的机制层主干已写：今天的自我给未来自我留一个 \\(\\beta\\) 折扣，老练自我为此买<a href="/econ/commitment-devices">承诺装置</a>，幼稚自我把拖延推到最后一刻。异常数据给这个博弈加刻度：跨「现在」的选择反转幅度决定 \\(\\beta\\)，对承诺装置的支付意愿是 \\(\\beta\\) 的显式上界估计。不这么做会错在哪：用单一期限问卷估出一个「贴现率」再外推全部期限，等于把函数形状当成水平读数；拿它给储蓄政策定价，方向与量级同时错。</p><p><span class="marginnote">数字实例：取 \\(\\beta=0.7\\)、\\(\\delta=0.99\\)。间隔同为一周：「今天对七天后」的有效折扣是 \\(\\beta\\delta\\approx0.693\\)；「一年后对一年零七天后」只有 \\(\\delta\\approx0.99\\)。同一个星期，两种待遇——共同差异效应的算术就这么两行。</span></p><p><span class="marginnote">直觉类比：\\(\\delta\\) 像给所有「未来提货」的订单统一打的长期折扣，\\(\\beta\\) 像凡是「今天提货」还要额外补的一道折扣。两笔报酬隔多远不重要，重要的是这单生意跨没跨过「今天」这条线。</span></p>',4)),(e(),A(r,null,{default:a(()=>[o(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NOW%5B%22%E4%BB%8A%E5%A4%A9%20100%20%E5%AF%B9%207%20%E5%A4%A9%E5%90%8E%20110%3A%20%E4%B8%80%E7%AB%AF%E6%98%AF%E7%8E%B0%E5%9C%A8%22%5D%20--%3E%20CROSS%5B%22%E9%97%B4%E9%9A%94%E8%B7%A8%E8%B6%8A%E6%96%AD%E7%82%B9%3A%20%E8%A2%AB%20%CE%B2%20%E9%A2%9D%E5%A4%96%E6%8A%98%E4%B8%80%E6%AC%A1%22%5D%0A%20%20FUT%5B%22%E4%B8%80%E5%B9%B4%E5%90%8E%20100%20%E5%AF%B9%E4%B8%80%E5%B9%B4%E9%9B%B6%207%20%E5%A4%A9%E5%90%8E%20110%3A%20%E4%B8%A4%E7%AB%AF%E9%83%BD%E5%9C%A8%E6%9C%AA%E6%9D%A5%22%5D%20--%3E%20SAME%5B%22%E9%97%B4%E9%9A%94%E4%B8%8D%E8%B7%A8%E6%96%AD%E7%82%B9%3A%20%E5%8F%AA%E6%9C%89%20%CE%B4%20%E8%AF%B4%E8%AF%9D%22%5D%0A%20%20CROSS%20--%3E%20REV%5B%22%E5%90%8C%E4%B8%80%E9%97%B4%E9%9A%94%2C%20%E9%80%89%E6%8B%A9%E5%8F%8D%E8%BD%AC%20%E2%86%92%20%E8%BF%99%E6%98%AF%20%CE%B2%20%E7%9A%84%E6%8C%87%E7%BA%B9%22%5D%0A%20%20SAME%20--%3E%20CONS%5B%22%E9%80%89%E6%8B%A9%E4%B8%8E%E4%BB%8A%E5%A4%A9%E7%89%88%E4%B8%80%E8%87%B4%20%E2%86%92%20%CE%B4%20%E5%8D%95%E7%8B%AC%E7%A8%B3%E4%BD%8F%E9%95%BF%E7%AB%AF%22%5D%0A%20%20FRONT%5B%22%E5%89%8D%E7%AB%AF%E5%BB%B6%E8%BF%9F%E5%8D%8F%E8%AE%AE%3A%20%E4%B8%A4%E9%80%89%E9%A1%B9%E9%83%BD%E6%8E%A8%E5%88%B0%E8%87%B3%E5%B0%91%E4%B8%80%E5%91%A8%E5%90%8E%22%5D%20-.-%3E%7C%22%E5%89%A5%E7%A6%BB%E3%80%8E%E7%AB%8B%E5%88%BB%E3%80%8F%E7%9A%84%E7%94%9C%E5%A4%B4%2C%20%E9%9C%B2%E5%87%BA%E7%BA%AF%20%CE%B4%22%7C%20NOW%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p>这张图回答的是：\\(\\beta\\) 与 \\(\\delta\\) 怎么被分开认出来。虚线那条是实验设计的关键一步——前端延迟把「立刻」的特别吸引力从数据里剥走，剩下的变异才干净地属于参数，而不是「现在」这个时点的光环。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指数贴现仍在长期利率、增长与资产定价里当默认，本课只标换件位置：行为证据集中在消费选择的短端。用<a href="/econ/commitment-devices">承诺装置</a>反推 \\(\\beta\\) 要防两个混淆：流动性约束会假性抬高 \\(\\beta\\)——想提前消费也拿不到现金；假想问卷会高估承诺意愿。也不把政策的时间不一致与个人现时偏差写进同一个方程，主干已划下那一刀。后课默认：谈现时偏差指 \\(\\beta\\)–\\(\\delta\\) 加测量协议；遇到新异常，先判「函数形状」还是「协议伪影」，再谈模型。</p><p><span class="marginnote">常见误区：把问卷里「隐含年贴现率 300%」当成人的长期耐心。那个数字来自短端、且「立刻兑现」自带甜头；换成前端延迟或大金额，同一个被试的隐含贴现率能掉一个数量级——贴现率是曲线，不是一个数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共同差异效应被 \\(\\beta\\) 吸收：折扣断点正好落在「现在对以后」上。</li><li>幅度、符号与延迟—加速不对称 \\(\\beta\\)–\\(\\delta\\) 吸不住，指回收益凹、损失平的价值函数。</li><li>辨识分工：是否跨「现在」动 \\(\\beta\\)，长端水平动 \\(\\delta\\)；前端延迟是分离两者的关键协议。</li><li>无前端延迟的假想问卷系统性高估现时偏差。</li><li>指数贴现在长端仍是默认，\\(\\beta\\)–\\(\\delta\\) 是短端换件。</li><li>出处：Thaler, <em>Economics Letters</em> 1981；Laibson, <em>QJE</em> 1997；O&#39;Donoghue and Rabin, <em>AER</em> 1999；Frederick, Loewenstein and O&#39;Donoghue, <em>JEL</em> 2002。</li></ul>',6))])}const u=n(d,[["render",p]]);export{h as __pageData,u as default};
